<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><p class="eyebrow">Operasional</p><h1>Pesanan</h1><form class="admin-filter" method="get"><label for="status">Status pesanan</label><select id="status" name="status"><option value="">Semua status</option><?php foreach(['pending_payment'=>'Menunggu Pembayaran','confirmed'=>'Dikonfirmasi','processing'=>'Diproses','ready_for_pickup'=>'Siap Diambil','out_for_delivery'=>'Sedang Diantar','completed'=>'Selesai','cancelled'=>'Dibatalkan'] as $value=>$label): ?><option value="<?= esc($value) ?>" <?= $status===$value?'selected':'' ?>><?= esc($label) ?></option><?php endforeach ?></select><button class="button button-small">Terapkan</button></form><div class="table-wrap"><table><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Metode</th><th>Jadwal</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><a href="<?= site_url('admin/pesanan/'.$order['id']) ?>"><?= esc($order['order_no']) ?></a><small><?= esc($order['created_at']) ?></small></td><td><?= esc($order['customer_name']) ?><small><?= esc($order['customer_phone']) ?></small></td><td><?= $order['fulfillment_type']==='pickup'?'Ambil':'Antar' ?></td><td><?= esc($order['pickup_date']) ?><small><?= esc($order['time_slot_snapshot']) ?></small></td><td>Rp<?= number_format((int)$order['total'],0,',','.') ?></td><td><?= esc($order['status']) ?></td></tr><?php endforeach ?></tbody></table></div><?= $this->endSection() ?>